import numpy as np

def sigmoid(z):
    return 1 / (1 + np.exp(-z))

def neuron(x, w, b):
    z = np.dot(w, x) + b
    return sigmoid(z)

x = np.array([0.5, 0.8, -0.2])
w = np.array([0.4, -0.6, 0.9])
b = 0.1

output = neuron(x, w, b)
print(f"neuron output: {output:.4f}")

